(()=>{
const $=id=>document.getElementById(id);const API=window.APP_CONFIG?.API_URL||"";let schools=[],history=[],items=[],current={},signer={kepala:{nama:"-",nip:""},bendahara:{nama:"-",nip:""},kegiatan:{nama:"-",nip:""}},settings={footer:"* Kuitansi ini sah sebagai bukti pembayaran yang sah dan dapat dipertanggungjawabkan"};
const rupiah=n=>new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(Number(n)||0);const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));const dateId=s=>s?new Intl.DateTimeFormat("id-ID",{day:"2-digit",month:"long",year:"numeric"}).format(new Date(s+"T00:00:00")):"-";
function toast(m){$("toast").textContent=m;$("toast").classList.add("show");setTimeout(()=>$("toast").classList.remove("show"),2800)}
function terbilang(n){const w=["nol","satu","dua","tiga","empat","lima","enam","tujuh","delapan","sembilan","sepuluh","sebelas"];n=Math.floor(Math.abs(Number(n)||0));const f=x=>x<12?w[x]:x<20?w[x-10]+" belas":x<100?f(Math.floor(x/10))+" puluh"+(x%10?" "+f(x%10):""):x<200?"seratus"+(x%100?" "+f(x%100):""):x<1000?f(Math.floor(x/100))+" ratus"+(x%100?" "+f(x%100):""):x<2000?"seribu"+(x%1000?" "+f(x%1000):""):x<1e6?f(Math.floor(x/1000))+" ribu"+(x%1000?" "+f(x%1000):""):x<1e9?f(Math.floor(x/1e6))+" juta"+(x%1e6?" "+f(x%1e6):""):x<1e12?f(Math.floor(x/1e9))+" miliar"+(x%1e9?" "+f(x%1e9):""):x<1e15?f(Math.floor(x/1e12))+" triliun"+(x%1e12?" "+f(x%1e12):""):"nilai terlalu besar";let s=f(n);return s[0].toUpperCase()+s.slice(1)+" Rupiah"}
async function api(action,data={}){if(!API)throw Error("API belum diatur. Isi public/config.js dengan URL Web App Apps Script.");const r=await fetch(API,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({action,...data})});const j=await r.json();if(!j.success)throw Error(j.message||"Permintaan gagal");return j}
function totals(r=current){const sub=items.reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.price)||0),0),d=Math.max(0,Number(r.discount)||0);return{subtotal:sub,total:Math.max(0,sub-d)}}
function schoolById(id){return schools.find(s=>String(s.id)===String(id))||schools[0]}
function blank(){const s=schoolById(current.schoolId)||schools[0];current={id:"",number:"",date:new Date().toISOString().slice(0,10),budgetYear:new Date().getFullYear(),schoolId:s?.id||"",payer:"",purpose:"",method:"Tunai",discount:0,notes:""};items=[{description:"",qty:1,price:0}];loadSigner();renderForm()}
function renderSchoolOptions(){const sel=$("schoolId");sel.innerHTML=schools.length?schools.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}${s.city?" — "+esc(s.city):""}</option>`).join(""):'<option value="">Belum ada sekolah</option>';if(current.schoolId)sel.value=current.schoolId;updateSchoolHeader()}
function updateSchoolHeader(){const s=schoolById(current.schoolId);$("activeSchoolTop").textContent=s?s.name:"Belum ada sekolah";$("schoolMini").textContent=s?s.name:"Belum dipilih"}
async function loadSigner(){const s=schoolById(current.schoolId);if(!s){signer={kepala:{nama:"-",nip:""},bendahara:{nama:"-",nip:""},kegiatan:{nama:"-",nip:""}};return}signer={kepala:{nama:s.kepala||"-",nip:s.kepalaNip||""},bendahara:{nama:s.bendahara||"-",nip:s.bendaharaNip||""},kegiatan:{nama:s.kegiatan||"-",nip:s.kegiatanNip||""}};$("kepalaNama").textContent=signer.kepala.nama;$("kepalaNip").textContent="NIP. "+signer.kepala.nip;$("bendaharaNama").textContent=signer.bendahara.nama;$("bendaharaNip").textContent="NIP. "+signer.bendahara.nip;$("kegiatanNama").textContent=signer.kegiatan.nama;$("kegiatanNip").textContent="NIP. "+signer.kegiatan.nip;renderReceipt()}
function sync(){["number","date","budgetYear","payer","purpose","method","discount","notes","schoolId"].forEach(k=>{current[k]=$(k).value});current.budgetYear=Number(current.budgetYear)||new Date().getFullYear();current.discount=Number(current.discount)||0}
function renderItems(){
$("items").innerHTML=`<div class="item header"><div>No</div><div>Uraian</div><div>Qty</div><div>Harga Satuan</div><div>Jumlah</div><div></div></div>`+items.map((x,i)=>`<div class="item"><div>${i+1}</div><input data-i="${i}" data-k="description" value="${esc(x.description)}" placeholder="Uraian"><input data-i="${i}" data-k="qty" type="number" min="1" value="${x.qty}"><input data-i="${i}" data-k="price" type="number" min="0" value="${x.price||""}"><div class="money">${rupiah(x.qty*x.price)}</div><button class="remove" data-r="${i}">×</button></div>`).join("");
$("items").querySelectorAll("input").forEach(e=>e.oninput=()=>{const i=+e.dataset.i,k=e.dataset.k;items[i][k]=k==="description"?e.value:Number(e.value)||0;renderItems();renderReceipt()});$("items").querySelectorAll("[data-r]").forEach(e=>e.onclick=()=>{items.splice(+e.dataset.r,1);if(!items.length)items.push({description:"",qty:1,price:0});renderItems();renderReceipt()})}
function renderForm(){renderSchoolOptions();["number","date","budgetYear","payer","purpose","method","discount","notes"].forEach(k=>$(k).value=current[k]??"");renderItems();loadSigner();renderReceipt()}
function receiptHtml(r=current,it=items,sign=signer,school=schoolById(r.schoolId)){const t={subtotal:it.reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.price)||0),0),total:0};t.total=Math.max(0,t.subtotal-(Number(r.discount)||0));const city=school?.city||"Jakarta";return `<div class="receipt"><div class="receipt-head"><div class="gov">PEMERINTAH PROVINSI DAERAH KHUSUS IBUKOTA JAKARTA DINAS PENDIDIKAN</div><div class="school">${esc(school?.name||"NAMA SEKOLAH")}</div><div class="addr">${esc(school?.address||"")}${city?" · "+esc(city):""}</div></div><div class="receipt-title">KUITANSI</div><div class="receipt-no">Nomor : <b>${esc(r.number||"-")}</b></div><span class="original">Lembar Asli</span><div class="budget">Tahun Anggaran : <b>${esc(r.budgetYear)}</b></div><div class="rline"><div class="label">TELAH DITERIMA DARI</div><div>:</div><div>${esc(r.payer||"........................................................")}</div></div><div class="rline"><div class="label">UANG SEJUMLAH</div><div>:</div><div class="amount-words">“${esc(terbilang(t.total))}”</div></div><div class="rline"><div class="label">UNTUK PEMBAYARAN</div><div>:</div><div>${esc(r.purpose||"........................................................................................")}</div></div><div class="total-row"><div class="total-box">JUMLAH RP. <strong>${rupiah(t.total).replace("Rp","").trim()} ,-</strong></div><div class="date-print">${esc(city)}, ${dateId(r.date)}</div></div><div class="sign-grid"><div><div class="sign-role">Setuju Dibayar,<b>KEPALA SEKOLAH</b></div><div class="sign-space"></div><div class="sign-name">${esc(sign.kepala.nama)}</div><div class="sign-nip">NIP. ${esc(sign.kepala.nip)}</div></div><div><div class="sign-role">Lunas Dibayar,<b>BENDAHARA</b></div><div class="sign-space"></div><div class="sign-name">${esc(sign.bendahara.nama)}</div><div class="sign-nip">NIP. ${esc(sign.bendahara.nip)}</div></div><div><div class="sign-role">Penerima Uang,<b>BENDAHARA KEGIATAN</b></div><div class="sign-space"></div><div class="sign-name">${esc(sign.kegiatan.nama)}</div><div class="sign-nip">NIP. ${esc(sign.kegiatan.nip)}</div></div></div><div class="receipt-foot">${esc(settings.footer||"")}</div></div>`}
function renderReceipt(){$("receipt").innerHTML=receiptHtml();const t=totals();$("subtotal").textContent=rupiah(t.subtotal);$("discountView").textContent=rupiah(current.discount);$("total").textContent=rupiah(t.total);updateSchoolHeader()}
async function save(){sync();if(!current.schoolId)return toast("Pilih sekolah terlebih dahulu.");if(!current.payer)return toast("Diterima dari wajib diisi.");if(!current.purpose)return toast("Untuk pembayaran wajib diisi.");if(!items.some(x=>String(x.description).trim()&&Number(x.price)>0))return toast("Tambahkan minimal satu item bernilai.");try{$("saveBtn").disabled=true;$('saveBtn').textContent="Menyimpan...";const j=await api("saveReceipt",{receipt:{...current,items}});current.id=j.data.id;current.number=j.data.number;toast("Kuitansi berhasil disimpan.");await loadHistory();renderForm()}catch(e){toast(e.message)}finally{$("saveBtn").disabled=false;$('saveBtn').textContent="▣ Simpan"}}
async function loadHistory(){try{const j=await api("listReceipts");history=j.data||[];renderHistory()}catch(e){if(API)toast(e.message)}}
function renderHistory(){const q=($('search').value||'').toLowerCase();const d=history.filter(x=>[x.number,x.payer,x.purpose,x.schoolName].join(' ').toLowerCase().includes(q));$('history').innerHTML=d.length?d.map(x=>`<div class="history-row"><input class="receipt-check" type="checkbox" data-id="${esc(x.id)}"><div class="hmain"><b>${esc(x.number)}</b><span>${esc(x.schoolName)} · ${dateId(x.date)} · ${esc(x.payer)}</span><small>${esc(x.purpose)}</small></div><div class="hamount"><b>${rupiah(x.total)}</b><div><button class="btn small" data-edit="${esc(x.id)}">Edit</button><button class="btn small" data-oneprint="${esc(x.id)}">Cetak</button><button class="btn small danger" data-del="${esc(x.id)}">Hapus</button></div></div></div>`).join(''):'<p>Belum ada kuitansi.</p>';$('selectAll').checked=false;updateSelected();document.querySelectorAll('.receipt-check').forEach(c=>c.onchange=updateSelected);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));document.querySelectorAll('[data-oneprint]').forEach(b=>b.onclick=()=>printMany([b.dataset.oneprint]));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>del(b.dataset.del))}
function selectedIds(){return [...document.querySelectorAll('.receipt-check:checked')].map(x=>x.dataset.id)}function updateSelected(){$('selectedCount').textContent=selectedIds().length+' terpilih'}
async function edit(id){const x=history.find(a=>String(a.id)===String(id));if(!x)return;current={...x};items=(x.items||[]).map(a=>({...a}));show('form');renderForm()}
async function del(id){if(!confirm('Hapus kuitansi ini?'))return;try{await api('deleteReceipt',{id});toast('Kuitansi dihapus.');await loadHistory()}catch(e){toast(e.message)}}
function printMany(ids){if(!ids.length)return toast('Pilih minimal satu kuitansi.');const chosen=history.filter(x=>ids.includes(String(x.id)));const html=`<!doctype html><html><head><meta charset="utf-8"><title>Cetak Kuitansi</title><style>${printCss()}</style></head><body>${chosen.map(x=>{const s=schools.find(a=>String(a.id)===String(x.schoolId))||{};const sg={kepala:{nama:s.kepala||'-',nip:s.kepalaNip||''},bendahara:{nama:s.bendahara||'-',nip:s.bendaharaNip||''},kegiatan:{nama:s.kegiatan||'-',nip:s.kegiatanNip||''}};return receiptHtml(x,x.items||[],sg,s)}).join('')}</body></html>`;const w=window.open('','_blank');if(!w)return toast('Popup diblokir browser. Izinkan popup untuk mencetak.');w.document.open();w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),500)}
function printCss(){return `.receipt{background:#fff;width:100%;min-height:260mm;border:1px solid #233a50;padding:12mm 14mm;color:#182c40;font-family:Arial,sans-serif;break-after:page;page-break-after:always}.receipt:last-child{break-after:auto;page-break-after:auto}.receipt-head{height:25mm;border-bottom:3px double #24384d;text-align:center;padding-top:2mm}.receipt-head .gov{font-size:9px;font-weight:bold}.receipt-head .school{font-size:18px;font-weight:900;margin-top:4px}.receipt-head .addr{font-size:8px;margin-top:3px}.receipt-title{text-align:center;font-weight:900;font-size:25px;letter-spacing:9px;margin:14px 0 1px}.receipt-no{text-align:center;font-size:8px}.original{float:right;color:#708399;font-size:8px;margin-top:-12px}.budget{display:inline-block;border:1px solid #334a60;padding:7px 12px;font-size:9px;margin-top:13px}.rline{display:grid;grid-template-columns:145px 15px 1fr;gap:5px;margin-top:13px;font-size:10px;line-height:1.55}.rline .label{font-weight:bold}.amount-words{background:#f2f7fb;border:1px solid #b8cce0;border-radius:3px;padding:8px 11px;font-weight:bold;font-style:italic}.total-row{border-top:1px solid #d7e0e8;border-bottom:1px solid #d7e0e8;margin-top:13px;padding:9px 0;display:flex;justify-content:space-between;align-items:center}.total-box{border:1px solid #263e55;border-radius:3px;padding:8px 13px;font-weight:bold;font-size:11px}.total-box strong{font-size:16px;margin-left:12px}.date-print{font-size:9px}.sign-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;text-align:center;margin-top:25px;border-top:1px solid #d8e0e7;padding-top:20px}.sign-role{font-size:9px;min-height:30px}.sign-role b{display:block;font-size:10px}.sign-space{height:68px}.sign-name{font-weight:bold;text-decoration:underline;font-size:9px}.sign-nip{font-size:8px;margin-top:3px}.receipt-foot{border-top:1px solid #d8e0e7;margin-top:22px;padding-top:8px;font-size:7px;color:#73879a}@page{size:A4;margin:8mm}@media print{body{margin:0}}`}
function show(v){document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));$(v+'View').classList.remove('hidden');document.querySelectorAll('.side').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='history')loadHistory();if(v==='schools')loadSchools()}
async function loadSchools(){try{const j=await api('listSchools');schools=j.data||[];renderSchoolOptions();renderSchoolsTable()}catch(e){if(API)toast(e.message)}}
function renderSchoolsTable(){$('schoolsTable').innerHTML=schools.length?`<table class="data-table"><thead><tr><th>Kode</th><th>Sekolah</th><th>Kepala Sekolah</th><th>Bendahara</th><th>Bendahara Kegiatan</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${schools.map(s=>`<tr><td>${esc(s.code)}</td><td><b>${esc(s.name)}</b><small>${esc(s.city)}</small></td><td>${esc(s.kepala)}<small>${esc(s.kepalaNip)}</small></td><td>${esc(s.bendahara)}<small>${esc(s.bendaharaNip)}</small></td><td>${esc(s.kegiatan)}<small>${esc(s.kegiatanNip)}</small></td><td>${s.active?'Aktif':'Tidak Aktif'}</td><td><button class="btn small" data-es="${esc(s.id)}">Edit</button></td></tr>`).join('')}</tbody></table>`:'<p>Belum ada sekolah.</p>';document.querySelectorAll('[data-es]').forEach(b=>b.onclick=()=>editSchool(b.dataset.es))}
function editSchool(id){const s=schools.find(x=>String(x.id)===String(id));if(!s)return;$('schoolForm').classList.remove('hidden');$('editSchoolId').value=s.id;[['scCode',s.code],['scName',s.name],['scAddress',s.address],['scCity',s.city],['scKepala',s.kepala],['scKepalaNip',s.kepalaNip],['scBendahara',s.bendahara],['scBendaharaNip',s.bendaharaNip],['scKegiatan',s.kegiatan],['scKegiatanNip',s.kegiatanNip],['scActive',String(s.active)]].forEach(([id,v])=>$(id).value=v||'')}
function newSchool(){['editSchoolId','scCode','scName','scAddress','scCity','scKepala','scKepalaNip','scBendahara','scBendaharaNip','scKegiatan','scKegiatanNip'].forEach(id=>$(id).value='');$('scActive').value='true';$('schoolForm').classList.remove('hidden')}
async function saveSchool(){const s={id:$('editSchoolId').value,code:$('scCode').value.trim(),name:$('scName').value.trim(),address:$('scAddress').value.trim(),city:$('scCity').value.trim(),kepala:$('scKepala').value.trim(),kepalaNip:$('scKepalaNip').value.trim(),bendahara:$('scBendahara').value.trim(),bendaharaNip:$('scBendaharaNip').value.trim(),kegiatan:$('scKegiatan').value.trim(),kegiatanNip:$('scKegiatanNip').value.trim(),active:$('scActive').value==='true'};if(!s.code||!s.name)return toast('Kode dan nama sekolah wajib diisi.');try{await api('saveSchool',{school:s});toast('Data sekolah tersimpan.');$('schoolForm').classList.add('hidden');await loadSchools();if(!current.schoolId)blank()}catch(e){toast(e.message)}}
async function saveSettings(){try{await api('saveSettings',{settings:{footer:$('sFooter').value}});settings.footer=$('sFooter').value;toast('Pengaturan tersimpan.');renderReceipt()}catch(e){toast(e.message)}}
$('newBtn').onclick=blank;$('addItem').onclick=()=>{items.push({description:'',qty:1,price:0});renderItems();renderReceipt()};$('saveBtn').onclick=save;$('resetBtn').onclick=blank;$('printBtn').onclick=()=>{sync();renderReceipt();window.print()};$('search').oninput=renderHistory;$('selectAll').onchange=e=>{document.querySelectorAll('.receipt-check').forEach(c=>c.checked=e.target.checked);updateSelected()};$('batchPrint').onclick=()=>printMany(selectedIds());$('newSchoolBtn').onclick=newSchool;$('cancelSchool').onclick=()=>$('schoolForm').classList.add('hidden');$('saveSchool').onclick=saveSchool;$('saveSettings').onclick=saveSettings;document.querySelectorAll('.side').forEach(b=>b.onclick=()=>show(b.dataset.view));$('schoolId').onchange=()=>{sync();loadSigner();renderReceipt()};['number','date','budgetYear','payer','purpose','method','discount','notes'].forEach(id=>$(id).addEventListener('input',()=>{sync();renderReceipt()}));
(async function init(){try{await loadSchools();const j=await api('getSettings');settings={...settings,...j.data};$('sFooter').value=settings.footer||'';if(schools.length)blank();else{items=[{description:'',qty:1,price:0}];current={date:new Date().toISOString().slice(0,10),budgetYear:new Date().getFullYear()};renderForm();toast('Tambahkan sekolah di menu Data Sekolah.')}}catch(e){items=[{description:'',qty:1,price:0}];current={date:new Date().toISOString().slice(0,10),budgetYear:new Date().getFullYear()};renderForm();if(API)toast(e.message)}})();
})();
